## 📋 תכנון:
נבנה משחק פשוט שבו שחקן שולט בכריש ומנסה לאכול דגים כדי לצבור נקודות. המשחק יכלול את הרכיבים הבאים:
1. **מסך פתיחה** - מציג את שם המשחק וכפתור להתחלת המשחק.
2. **משחק** - המסך המרכזי שבו הכריש ינוע, דגים יופיעו אקראית, והשחקן יוכל לאכול את הדגים.
3. **ציון** - מונה את הנקודות שהשחקן צבר.
4. **מסך סיום** - מציג את הציון הסופי עם אפשרות להתחיל מחדש.

## 🚀 איך להריץ:
1. תוודא שיש לך את Node.js מותקן.
2. צור תיקייה חדשה ופתח אותה בטרמינל.
3. התקן את הספריות הנדרשות:
   ```bash
   npm init -y
   npm install express socket.io
   ```
4. צור קובץ `index.html` והעתק לתוכו את הקוד הבא.
5. צור קובץ `server.js` והעתק לתוכו את הקוד הבא.
6. הרץ את השרת:
   ```bash
   node server.js
   ```
7. פתח דפדפן והכנס לכתובת `http://localhost:3000`.

### קוד HTML (`index.html`):
```html
<!DOCTYPE html>
<html lang="he">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>משחק כריש</title>
    <style>
        body { display: flex; justify-content: center; align-items: center; height: 100vh; background-color: #e0f7fa; }
        canvas { border: 2px solid #00796b; }
    </style>
</head>
<body>
    <canvas id="gameCanvas" width="800" height="600"></canvas>
    <script src="/socket.io/socket.io.js"></script>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        const socket = io();

        let shark = { x: 400, y: 300, width: 50, height: 30 };
        let fish = [];
        let score = 0;

        function drawShark() {
            ctx.fillStyle = '#00796b';
            ctx.fillRect(shark.x, shark.y, shark.width, shark.height);
        }

        function drawFish() {
            ctx.fillStyle = '#ffab00';
            fish.forEach(f => {
                ctx.fillRect(f.x, f.y, f.width, f.height);
            });
        }

        function updateGameArea() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            drawShark();
            drawFish();
            socket.emit('update', { shark, fish, score });
        }

        document.addEventListener('keydown', (event) => {
            if (event.key === 'ArrowUp') shark.y -= 10;
            if (event.key === 'ArrowDown') shark.y += 10;
            if (event.key === 'ArrowLeft') shark.x -= 10;
            if (event.key === 'ArrowRight') shark.x += 10;
        });

        socket.on('newFish', (newFish) => {
            fish.push(newFish);
        });

        socket.on('updateScore', (newScore) => {
            score = newScore;
        });

        setInterval(updateGameArea, 100);
    </script>
</body>
</html>
```

### קוד Node.js (`server.js`):
```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

let fish = [];
let score = 0;

app.use(express.static('.'));

function spawnFish() {
    const newFish = {
        x: Math.random() * 800,
        y: Math.random() * 600,
        width: 20,
        height: 10
    };
    fish.push(newFish);
    io.emit('newFish', newFish);
}

io.on('connection', (socket) => {
    console.log('User connected');

    socket.on('update', (data) => {
        const { shark } = data;

        fish = fish.filter((f) => {
            if (shark.x < f.x + f.width && shark.x + shark.width > f.x &&
                shark.y < f.y + f.height && shark.y + shark.height > f.y) {
                score++;
                io.emit('updateScore', score);
                return false; // Remove fish
            }
            return true; // Keep fish
        });
    });
});

setInterval(spawnFish, 2000);

server.listen(3000, () => {
    console.log('Server is running on http://localhost:3000');
});
```

