            font-size: 24px;
            color: #00796b;
        }
    </style>
</head>
<body>
    <div id="score">נקודות: 0</div>
    <canvas id="gameCanvas" width="800" height="600"></canvas>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        const scoreDisplay = document.getElementById('score');

        let shark = { x: 400, y: 300, width: 50, height: 30 };
        let fish = [];
        let score = 0;

        function drawShark() {
            ctx.fillStyle = '#00796b';
            ctx.fillRect(shark.x, shark.y, shark.width, shark.height);
        }

        function drawFish() {
            ctx.fillStyle = '#ffab00';
            fish.forEach(f => {
                ctx.fillRect(f.x, f.y, f.width, f.height);
            });
        }

        function updateGameArea() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            drawShark();
            drawFish();
            scoreDisplay.innerText = `נקודות: ${score}`;
        }

        function spawnFish() {
            const newFish = {
                x: Math.random() * (canvas.width - 20),
                y: Math.random() * (canvas.height - 10),
                width: 20,
                height: 10
            };
            fish.push(newFish);
        }

        function checkCollision() {
            fish = fish.filter(f => {
                if (shark.x < f.x + f.width && shark.x + shark.width > f.x &&
                    shark.y < f.y + f.height && shark.y + shark.height > f.y) {
                    score++;
                    return false; // Remove fish
                }
                return true; // Keep fish
            });
        }

        document.addEventListener('keydown', (event) => {
            if (event.key === 'ArrowUp' && shark.y > 0) shark.y -= 10;
            if (event.key === 'ArrowDown' && shark.y < canvas.height - shark.height) shark.y += 10;
            if (event.key === 'ArrowLeft' && shark.x > 0) shark.x -= 10;
            if (event.key === 'ArrowRight' && shark.x < canvas.width - shark.width) shark.x += 10;
            checkCollision();
        });

        setInterval(() => {
            spawnFish();
            updateGameArea();
        }, 100);

    </script>
</body>
</html>
